import java.util.TimeZone;

public class AgentBRT_Lang_50_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        int style = java.text.DateFormat.SHORT;
        TimeZone timeZone1 = TimeZone.getTimeZone("GMT");
        TimeZone timeZone2 = TimeZone.getTimeZone("PST");
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateInstance(style, timeZone1, locale);
        FastDateFormat format2 = FastDateFormat.getDateInstance(style, timeZone2, locale);

        assertNotSame("FastDateFormat instances should be different for different time zones", format1, format2);
    }
}

